package main

import (
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(num()), int(num())
	ans := make([]int64, n)
	st := []int{}
	var prev int64
	for k := 0; k < m; k++ {
		parts := strings.Split(token(), ":")
		fid, _ := strconv.Atoi(parts[0])
		ts, _ := strconv.ParseInt(parts[2], 10, 64)
		if parts[1] == "start" {
			if len(st) > 0 {
				ans[st[len(st)-1]] += ts - prev
			}
			st = append(st, fid)
			prev = ts
		} else {
			// The end timestamp itself belongs to the finishing call.
			ans[st[len(st)-1]] += ts - prev + 1
			st = st[:len(st)-1]
			prev = ts + 1
		}
	}
	out := []byte{}
	for i, v := range ans {
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, v, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
